dict(id='6.7.2',sub=E,nb=['ca','eco'],ch=['eco-ch07'],tag='M',t='Environmental costs of data centres',
 ctx='Capacity rose from about 520 MW (2020) to nearly 1.5 GW (mid-2026); could reach 6.5 GW by 2030.',
 pts=['Power use about 13 TWh (2024) to 57 TWh by 2030 (S&P Global). A 100 MW centre uses about 2 million litres of water a day (CEEW); national use could reach 358 billion litres a year by 2030. Clusters in water-stressed Mumbai, Hyderabad, Bengaluru, NCR. A 2026 Cambridge study links data centres to about 2°C higher land-surface temperature within 10 km.',
 'Gaps: no common standards, no water disclosure, grid assessment not mandatory; Gujarat requires 51% green energy; Maharashtra cut from 100% to 51%.'],pro=[],mains=[],kw='',pyq=''),
